/* Huyết Lệ Thôn — lồng tiếng tiếng Việt. Tạo bởi tools/build_vo.py. */
(function(H){H.VO={dur:{"C00": 3.2, "C01": 2.66, "C02": 1.98, "C03": 6.95, "NC01": 5.0, "NC02": 4.0, "NC03": 2.99, "NC04": 2.7, "NC05": 1.62, "NC06": 2.02, "NC07": 2.63, "NC08": 3.28, "NC09": 5.62, "NC10": 2.41, "NC11": 3.64, "NC12": 5.65, "NC13": 2.56, "NC14": 3.38, "NC15": 2.3, "NC16": 3.6, "NC17": 4.82, "NC18": 5.44, "NC19": 4.07, "NC20": 3.46, "NC21": 4.03, "NC22": 3.67, "NC23": 5.04, "NC24": 2.23, "NC25": 4.03, "NC26": 7.56, "C07": 4.61, "C08": 2.59, "C09": 3.49, "C10": 4.57, "C11": 2.38, "C12": 5.15, "C13": 2.99, "C14": 4.25, "C15": 0.79, "C16": 5.87, "C17": 6.19, "C18": 6.7, "C19": 4.97, "C20": 4.21, "C21": 5.62, "C22": 3.49, "C23": 6.88, "C24": 4.75, "C25": 5.94, "C26": 2.05, "C27": 2.48, "C28": 7.27, "C29": 6.34, "C30": 6.98, "C31": 3.74, "C32": 5.54, "C33": 8.03, "C34": 6.7, "C35": 3.6, "M00": 5.87, "M01": 3.2, "M02": 4.46, "M03": 2.77, "M10": 3.31, "M11": 4.5, "M12": 5.54, "M13": 1.66, "M20": 3.64, "M21": 2.88, "M22": 2.99, "M23": 2.88, "NL01": 5.94, "NL02": 2.41, "L_gateLocked": 3.85, "L_gateOpen": 3.92, "L_needCrank": 4.64, "L_crankPlaced": 2.02, "L_ambush": 2.3, "L_stunned": 2.95, "L_manorLocked": 2.52, "L_manorOpen": 3.35, "L_safeHint": 5.51, "L_gotScroll": 4.5, "L_graveyard": 3.96, "L_offering2": 1.4, "L_offering1": 1.33, "L_allOfferings": 2.09, "L_templeLocked": 4.21, "L_templeOpen": 2.63, "L_altarNeed": 2.12, "L_lowBattery": 1.12, "L_noFilm": 1.94, "L_ringFound": 4.54, "L_tuanAfter": 3.67, "L_haAfter": 3.85, "NL03": 2.81, "NL04": 3.35, "NL05": 4.61, "NL06": 4.1, "NL07": 3.17, "NL08": 3.38, "NL09": 4.32, "NL10": 4.82, "NL11": 3.1, "NL12": 4.9, "NL13": 3.35, "NL14": 4.0, "L_photo0": 2.52, "L_photo1": 2.34, "L_photo2": 2.74, "E_true0": 1.19, "E_true1": 6.55, "E_true2": 4.79, "E_true3": 6.01, "E_true4": 7.42, "E_true5": 6.84, "E_true6": 4.9, "E_bad0": 1.51, "E_bad1": 4.79, "E_bad2": 3.35, "E_bad3": 5.54, "E_bad4": 2.95, "E_bad5": 5.87, "E_bad6": 1.94, "E_best1": 6.66, "E_best2": 9.25, "E_best3": 2.2, "E_best4": 8.86, "E_best5": 8.64, "E_best6": 11.09, "E_best7": 5.98, "NE01": 1.33, "NE02": 7.2, "NE03": 8.89, "NE04": 6.52, "NE05": 7.6, "NE06": 1.19, "NE07": 5.44},t:{"Ba giờ trước khi vạt núi sạt xuống.": "C00", "Chị Linh ơi, bản đồ có vẽ lối này đâu?": "C01", "Cứ đi đi. Sắp tới rồi.": "C02", "Mùa thu năm 1994. Bão số 6 cuốn mất con đường sau lưng chúng tôi.": "C03", "Linh... Tuấn... Hà... mọi người đâu cả rồi?": "NC01", "Dấu chân ba người, đi xuống rừng. Sao lại bỏ mình lại?": "NC02", "Máy ảnh của ông nội... nó văng đâu quanh xe.": "NC03", "Miếu Sơn Thần... ai còn thắp nến ở đây?": "NC04", "...Linh? Hà?": "NC05", "Đừng theo ánh đèn đỏ.": "NC06", "Qua sông... trước khi trăng đứng đỉnh đầu.": "NC07", "Áo trắng... Hà tả một người áo đỏ cơ mà.": "NC08", "Trạm đo đạc bên sông Âm, đêm 23 tháng 9 năm 1934.": "NC09", "Nó tới rồi! Lộc, đứng sau lưng tôi!": "NC10", "Courez! Chạy đi, ông ơi, chạy đi!": "NC11", "Người lính Pháp quay lưng bỏ chạy. Thứ áo đỏ lướt qua cậu bé như không hề thấy cậu.": "NC12", "Ông nội... ông đã bảo ông ấy chạy.": "NC13", "Cầu treo đứt rồi. Cả hai đầu.": "NC14", "Bên kia sông... có người đứng.": "NC15", "Áo đỏ. Tóc dài chấm đất. Đúng như Hà tả.": "NC16", "Phải xuôi bờ sông. Có bến đò thì phải có thuyền.": "NC17", "Bến Dưới, tháng Năm năm Giáp Tuất — 1874.": "NC18", "Buộc đá vào chân. Sông sâu, nước chảy, trôi đi đâu thì đi.": "NC19", "Bẩm quan... nước sông này cả làng gánh về uống.": "NC20", "Thì bảo chúng nó uống nước giếng. Đứa nào hé răng, ta cho xuống theo.": "NC21", "Dịch không đến từ cái giếng. Nó đến từ chính cái bến này.": "NC22", "Sợi cáp rên lên từng hồi. Con đò trôi vào màn sương.": "NC23", "Có ai... đứng trên mặt nước.": "NC24", "Áo trắng phía trước... vậy cái thứ đang thở sau gáy mình là—": "NC25", "Tấm ảnh hiện dần trong đầu Minh: hai người đàn bà. Một đứng chắn trước mũi đò. Một đứng sát sau lưng anh.": "NC26", "Sợi xích tự tuột khỏi cổng, như thể chỉ chờ đúng con số ấy.": "C07", "...Hà? Hà, phải em không?": "C08", "Đừng tắt đèn, Minh ạ... chị ấy đi theo tiếng chân...": "C09", "Ba lô của Tuấn. Đồng hồ đeo tay dừng ở 0 giờ 49.": "C10", "Dây thừng thả xuống giếng... TUẤN!": "C11", "...đừng kéo tao lên vội... dưới này có hai người, Minh ạ... họ nắm tay nhau...": "C12", "Gương đồng... và một chiếc chìa khoá.": "C13", "Sợi dây tời bỗng căng lên. Có thứ gì đó đang trèo theo.": "C14", "CHẠY!": "C15", "Ta, Đoàn Văn Khải, viết bằng máu mình vì mực không chịu ăn giấy nữa.": "C16", "Thằng Khang con ta không chết vì dịch. Nó định lên huyện tố cha nó bán thóc phát chẩn.": "C17", "Ta chỉ sai tuần đinh giam nó. Chúng nặng tay. Trước lúc trời sáng, ta thả con ta xuống giếng.": "C18", "Rồi ta cần một con yêu nữ, để cả làng khỏi hỏi vì sao nước giếng đỏ.": "C19", "Người làm chứng điểm chỉ: Phó Văn Bảy... Trần Sửu.": "C20", "Họ Đoàn. Họ Phó. Họ Trần. ...Linh. Mình. Tuấn.": "C21", "Đừng lại gần! ...Minh? Là anh thật à?": "C22", "Chị ấy không hại em. Chị ấy đứng ngoài cửa suốt, mỗi lần mấy cái bóng cầm đuốc đi qua.": "C23", "Chị ấy chỉ đuổi anh, anh Tuấn... và chị Linh. Sao lại đúng ba người?": "C24", "Em không ra đâu. Cầm lấy cuộn băng này — của chị Linh. Chị ấy dặn đừng cho anh nghe trước khi tới Đình.": "C25", "...Em nghe rồi, phải không Hà?": "C26", "Cậu có đôi mắt của thằng Lộc cháu tôi.": "C27", "Sáu mươi năm trước nó dẫn đường cho đoàn đo đạc Tây lên đây. Chỉ mình nó ra được — vì nó dám chụp thẳng mặt nàng.": "C28", "Cái máy ảnh ấy giờ đeo trên cổ cậu. Làng không gọi bừa đâu. Làng gọi con cháu về trả nợ.": "C29", "Còn một thứ tôi không dám chôn: nhẫn bạc của cậu Khang. Tôi giấu ở miếu nhỏ dưới gốc đa. Soi gương mà tìm.": "C30", "Gọi đúng tên thì nàng đi. Nhưng dưới giếng có hai người.": "C31", "Đình làng, đêm rằm tháng Bảy. Then cửa đã cài — từ bên ngoài.": "C32", "Lệ ơi... mẹ không oán ai. Mẹ chỉ xin một người — một người thôi — nhớ lấy tên con.": "C33", "Bà không nguyền rủa ai cả. Lời nguyền là của những kẻ đứng ngoài, nghe hết, và không rút then.": "C34", "Minh... đừng vào. Chính em đưa mọi người tới đây.": "C35", "Rằm tháng Bảy, năm Giáp Tuất — 1874. Chính đường nhà Lý trưởng.": "M00", "Trói nó lại. Bảy thước lụa điều, cho nó khỏi hoá về.": "M01", "Con sắc thuốc cho con các người... sao không ai nhìn con?": "M02", "Trên vách hiện một con số: 3.": "M03", "Cũng đêm ấy, họ dồn cha mẹ nàng vào trong Đình.": "M10", "Lệ ơi! Đừng nhận! Con không làm gì sai cả!": "M11", "Người gác đình cài then từ bên ngoài. Tay ông ta run tới mức phải cài hai lần.": "M12", "Tro xếp thành con số 7.": "M13", "Họ thả nàng xuống Giếng Cổ lúc 0 giờ 49.": "M20", "Lấp đá lại. Từ nay cấm nhắc tên hai đứa nó.": "M21", "“Hai đứa”...? Biên bản chỉ ghi có một người.": "M22", "Nước nhỏ giọt thành con số 5.": "M23", "Minh: Đầu đau như búa bổ... Đèn pin vẫn còn. Máy ảnh của ông — nó văng đâu đó quanh xe.": "NL01", "Minh: Máy ảnh của ông nội. Vẫn còn phim.": "NL02", "Minh: Khoá số bốn vòng. Phải có manh mối quanh đây... tấm bia đá kia?": "L_gateLocked", "Minh: Xích tự tuột ra. Như thể nó chỉ chờ mình nói đúng năm.": "L_gateOpen", "Minh: Tời giếng mất tay quay. Tuấn có nhắc... ai đó đã giấu nó trong nhà.": "L_needCrank", "Minh: Vừa khít. Nào... kéo lên.": "L_crankPlaced", "Minh: Cái gì đang trèo lên theo sợi dây—— CHẠY!": "L_ambush", "Minh: Đèn flash làm nó tan đi... nhưng nó sẽ trở lại.": "L_stunned", "Minh: Khoá đồng. Cần chìa khoá của nhà Lý trưởng.": "L_manorLocked", "Minh: Trong này lạnh hơn ngoài mưa. Thử nhìn qua ống ngắm xem...": "L_manorOpen", "Minh: Két ba số. Biên bản ghi: TRÓI — THIÊU — DÌM. Ảnh sẽ cho mình thứ tự.": "L_safeHint", "Minh: Huyết Thư. Lão ta đã tự thú... rồi khoá nó lại suốt một trăm hai mươi năm.": "L_gotScroll", "Minh: Nghĩa địa. Soi gương đồng... vệt sáng sẽ chỉ hướng lễ vật.": "L_graveyard", "Minh: Còn 2 lễ vật nữa.": "L_offering2", "Minh: Còn 1 lễ vật nữa.": "L_offering1", "Minh: Đủ ba lễ vật. Lên Đình thôi.": "L_allOfferings", "Minh: Cửa Đình dán kín bùa. Linh nói cần lời thú tội của kẻ chủ mưu...": "L_templeLocked", "Minh: Bùa tự cháy thành tro khi Huyết Thư đến gần.": "L_templeOpen", "Minh: Đàn Ngũ Hành. Còn thiếu lễ vật.": "L_altarNeed", "Minh: Pin sắp hết...": "L_lowBattery", "Minh: Hết phim rồi.": "L_noFilm", "Minh: Nhẫn bạc. Mặt trong khắc chữ \"Lệ\". Người ấy đã định về đón cô.": "L_ringFound", "Minh: Tuấn còn sống. Nhưng muốn kéo cậu ấy lên thì phải có tay quay.": "L_tuanAfter", "Minh: Hà an toàn — vì Hà không mang họ của ai trong ba người đó.": "L_haAfter", "Minh: Dấu chân ba người đi xuống rừng. Mình phải theo.": "NL03", "Minh: Cô ấy chỉ về phía đông bắc... nơi có ánh lửa tàn.": "NL04", "Minh: Lều tối đen kịt, mùi hoá chất rửa ảnh. Thử chụp đèn flash vào trong xem.": "NL05", "Minh: Hòm sắt khoá bốn số. Morel phải ghi mã ở đâu đó trong trạm.": "NL06", "Minh: Chìa khoá đò... và trang cuối nhật trình của Morel.": "NL07", "Minh: Đứng yên. Nhìn thẳng vào nó. Đừng quay lưng...": "NL08", "Minh: Nó lùi lại rồi. Ông nội nói đúng.": "NL09", "Minh: Dây đò bị khoá xích. Phải có chìa — nhật trình nhắc tới một cái hòm sắt ở trạm đo đạc.": "NL10", "Minh: Chìa vừa ổ khoá. Kéo dây đò sang bờ bên kia...": "NL11", "Minh: Bờ bắc. Lối mòn rừng tre dẫn lên núi — xa xa có ánh đèn lồng đỏ.": "NL12", "Minh: Xác thuyền buôn còn ngập nửa thân. Thử chụp một kiểu...": "NL13", "Minh: Cầu đứt cả hai đầu. Phải xuôi bờ sông xuống bến đò.": "NL14", "Ảnh 1/3 — TRÓI: trên vách hiện số 3.": "L_photo0", "Ảnh 2/3 — THIÊU: tro xếp thành số 7.": "L_photo1", "Ảnh 3/3 — DÌM: nước nhỏ giọt thành số 5.": "L_photo2", "“Nguyễn Thị Lệ.”": "E_true0", "Ngọn lửa trên đàn chuyển từ đỏ sang trắng. Bảy thước lụa điều rơi khỏi cổ tay nàng, từng vòng một.": "E_true1", "Lần đầu tiên sau một trăm hai mươi năm, có người gọi nàng bằng cái tên mẹ đặt.": "E_true2", "Nàng thôi khóc. Nhưng trước khi tan đi, nàng ngoái nhìn về phía cái giếng — rất lâu.": "E_true3", "Trăng lặn. Mưa tạnh. Dưới gốc đa có hai người nằm thiếp đi: Linh và Hà. Còn thở.": "E_true4", "Tuấn không có ở đó. Đội cứu hộ tìm ba ngày, chỉ thấy một chiếc đồng hồ dừng ở 0 giờ 49.": "E_true5", "Vòng lặp đã đứt. Nhưng dưới giếng vẫn còn một người chưa ai gọi tên.": "E_true6", "Ngọn lửa tắt phụt.": "E_bad0", "Nàng nghiêng đầu nhìn bạn — rất lâu — như nhìn thêm một người làng nữa.": "E_bad1", "“Các người... vẫn gọi ta bằng cái tên ấy.”": "E_bad2", "Cửa Đình đóng sầm. Bên ngoài có tiếng then cài. Rồi tiếng đuốc.": "E_bad3", "Đồng hồ chỉ 0 giờ 49.": "E_bad4", "Mùa thu năm 1994. Cơn bão cuốn trôi con đường sau lưng chúng tôi...": "E_bad5", "Sáu mươi năm một vòng.": "E_bad6", "Bạn đặt chiếc nhẫn bạc lên Đàn Ngũ Hành. “Khang gửi. Anh ấy không bỏ cô. Anh ấy xuống đó trước cô.”": "E_best1", "Ngọn lửa trắng tách làm hai. Từ phía giếng có một bóng người bước vào Đình — ướt sũng, lóng ngóng, như kẻ về muộn một trăm hai mươi năm.": "E_best2", "Lần này không ai cài then.": "E_best3", "Hai cái bóng đi qua bạn, qua ngưỡng cửa, ra sân. Nàng đeo nhẫn. Nàng cười — bạn chưa từng nghĩ khuôn mặt ấy cười được.": "E_best4", "Trăng lặn. Mưa tạnh. Dưới gốc đa có ba người nằm thiếp đi: Linh, Hà, và Tuấn — tay còn nắm sợi dây thừng.": "E_best5", "Sáng hôm sau đội cứu hộ tìm thấy bốn người trên một bãi đất trống. Không có ngôi làng nào ở đó. Chỉ có một cái giếng cạn, và dưới đáy, hai bộ hài cốt nằm quay mặt vào nhau.": "E_best6", "Người ta chôn họ chung một mộ. Bia chỉ khắc hai cái tên. Không có chữ “nương” nào cả.": "E_best7", "Bạn quay lưng.": "NE01", "Sau lưng, ngọn lửa trên đàn tắt phụt. Tiếng Linh gọi tên bạn, rồi tiếng Hà, rồi không còn tiếng ai.": "NE02", "Cổng làng mở sẵn. Lối mòn rừng tre, con sông, cánh rừng — tất cả rẽ ra cho bạn đi qua, như thể làng chỉ chờ đúng điều ấy.": "NE03", "Thứ áo đỏ không đuổi theo. Nó không cần. Bạn vừa làm đúng điều ông nội bạn đã làm sáu mươi năm trước.": "NE04", "Năm 2054. Một ông già đặt chiếc máy ảnh Liên Xô vào tay đứa cháu nội, kèm một mảnh giấy gấp tư.": "NE05", "“Đừng quay lưng.”": "NE06", "Ông không kể vì sao. Ông chỉ biết năm ấy lại là năm Giáp Tuất.": "NE07"},d:{"C00": "", "C01": "", "C02": "", "C03": "", "NC01": "", "NC02": "", "NC03": "", "NC04": "", "NC05": "", "NC06": "", "NC07": "", "NC08": "", "NC09": "", "NC10": "", "NC11": "", "NC12": "", "NC13": "", "NC14": "", "NC15": "", "NC16": "", "NC17": "", "NC18": "", "NC19": "", "NC20": "", "NC21": "", "NC22": "", "NC23": "", "NC24": "", "NC25": "", "NC26": "", "C07": "", "C08": "", "C09": "", "C10": "", "C11": "", "C12": "", "C13": "", "C14": "", "C15": "", "C16": "", "C17": "", "C18": "", "C19": "", "C20": "", "C21": "", "C22": "", "C23": "", "C24": "", "C25": "", "C26": "", "C27": "", "C28": "", "C29": "", "C30": "", "C31": "", "C32": "", "C33": "", "C34": "", "C35": "", "M00": "", "M01": "", "M02": "", "M03": "", "M10": "", "M11": "", "M12": "", "M13": "", "M20": "", "M21": "", "M22": "", "M23": "", "NL01": "", "NL02": "", "L_gateLocked": "", "L_gateOpen": "", "L_needCrank": "", "L_crankPlaced": "", "L_ambush": "", "L_stunned": "", "L_manorLocked": "", "L_manorOpen": "", "L_safeHint": "", "L_gotScroll": "", "L_graveyard": "", "L_offering2": "", "L_offering1": "", "L_allOfferings": "", "L_templeLocked": "", "L_templeOpen": "", "L_altarNeed": "", "L_lowBattery": "", "L_noFilm": "", "L_ringFound": "", "L_tuanAfter": "", "L_haAfter": "", "NL03": "", "NL04": "", "NL05": "", "NL06": "", "NL07": "", "NL08": "", "NL09": "", "NL10": "", "NL11": "", "NL12": "", "NL13": "", "NL14": "", "L_photo0": "", "L_photo1": "", "L_photo2": "", "E_true0": "", "E_true1": "", "E_true2": "", "E_true3": "", "E_true4": "", "E_true5": "", "E_true6": "", "E_bad0": "", "E_bad1": "", "E_bad2": "", "E_bad3": "", "E_bad4": "", "E_bad5": "", "E_bad6": "", "E_best1": "", "E_best2": "", "E_best3": "", "E_best4": "", "E_best5": "", "E_best6": "", "E_best7": "", "NE01": "", "NE02": "", "NE03": "", "NE04": "", "NE05": "", "NE06": "", "NE07": ""}};})(window.HuyetLeThon);
